          break;
        case "ArrowUp":
          spherical.phi -= step;
          break;
        case "ArrowDown":
          spherical.phi += step;
          break;
        case "+":
        case "=":
          spherical.radius *= 0.8;
          break;
        case "-":
        case "_":
          spherical.radius /= 0.8;
          break;
        default:
