python - <<'EOF'
def edit(p, a, b, n=1):
    s=open(p,encoding='utf-8').read(); assert s.count(a)==n,(p,a,s.count(a)); open(p,'w',encoding='utf-8',newline='').write(s.replace(a,b))
# shared type
s=open('src/lib/maps.ts',encoding='utf-8').read()
s+='''
/**
 * Where a map was opened from, carried in the router's location state so the map
 * page can offer "← Community" or "← Your maps". Maps opened from a shared link or
 * QR code have none, and show the Path logo instead.
 */
export interface MapOrigin {
  from: string;
  fromLabel: string;
  mapName?: string;
}

export function readMapOrigin(state: unknown): MapOrigin | null {
  const value = state as Partial<MapOrigin> | null;
  return value && typeof value.from === "string" && typeof value.fromLabel === "string"
    ? { from: value.from, fromLabel: value.fromLabel, mapName: value.mapName }
    : null;
}
'''
open('src/lib/maps.ts','w',encoding='utf-8',newline='').write(s)

c='src/components/MapCard.tsx'
edit(c,'import type { MapSummary } from "../lib/maps";','import type { MapOrigin, MapSummary } from "../lib/maps";')
edit(c,'export default function MapCard({ map, sample = false }: { map: MapSummary; sample?: boolean }) {','''export default function MapCard({
  map,
  sample = false,
  origin,
}: {
  map: MapSummary;
  sample?: boolean;
  /** The page this card is on, so the map can offer a way back to it. */
  origin?: { path: string; label: string };
}) {''')
edit(c,'''    <Link
      to={map.sharePath}''','''    <Link
      to={map.sharePath}
      state={origin ? ({ from: origin.path, fromLabel: origin.label, mapName: map.name } satisfies MapOrigin) : undefined}''')
edit('src/routes/Community.tsx','<MapCard map={map} />','<MapCard map={map} origin={{ path: "/community", label: "Community" }} />')
edit('src/routes/MyMaps.tsx','<MapCard map={map} sample />','<MapCard map={map} sample origin={{ path: "/maps", label: "Your maps" }} />')
EOF
echo ok

