def edit(p, a, b, n=1):
    s=open(p,encoding='utf-8').read(); assert s.count(a)==n,(p,a,s.count(a)); open(p,'w',encoding='utf-8',newline='').write(s.replace(a,b))
g='src/routes/GuestView.tsx'
s=open(g,encoding='utf-8').read()
# call site props
a='''        <ViewerChrome
          shareId={state.meta.shareId}
          scan={state.scan}
          showHint'''
assert s.count(a)==1
s=s.replace(a,'''        <ViewerChrome
          showHint''')
# component signature
a='''function ViewerChrome({
  shareId,
  scan,
  showHint,'''
assert s.count(a)==1
s=s.replace(a,'''function ViewerChrome({
  showHint,''')
a='''}: {
  shareId: string;
  scan: PointScan;
  showHint: boolean;'''
assert s.count(a)==1
s=s.replace(a,'''}: {
  showHint: boolean;''')
a='''  const location = useLocation();
  const downsampled = scan.count < scan.sourceCount;
  return ('''
assert s.count(a)==1
s=s.replace(a,'''  const location = useLocation();
  const navigate = useNavigate();
  const origin = readMapOrigin(location.state);
  // Names come from the card the map was opened from. The API has no map names yet (#3).
  const mapName = origin?.mapName ?? "Shared map";
  // Going back through history keeps the previous page's filters and scroll position.
  // A map opened straight from a link or QR has no previous page in Path.
  const canGoBack = origin !== null && (window.history.state as { idx?: number } | null)?.idx !== 0;
  return (''')
a='''        <div>
          <Link
            to="/"
            className="pointer-events-auto font-display text-2xl leading-none font-black tracking-wide text-paper"
          >
            Path
          </Link>
          <div className="mt-1 font-mono text-xs leading-relaxed text-sage">
            <span title={shareId}>scan {shareId.slice(0, 8)}</span> · {scan.count.toLocaleString()} pts
            {downsampled ? ` of ${scan.sourceCount.toLocaleString()}` : ""}
          </div>
        </div>
        <Link
          to="/settings"
          state={{ from: location.pathname }}'''
assert s.count(a)==1
s=s.replace(a,'''        <div className="min-w-0">
          {origin ? (
            <Link
              to={origin.from}
              onClick={(event) => {
                if (canGoBack) {
                  event.preventDefault();
                  navigate(-1);
                }
              }}
              className="pointer-events-auto inline-flex min-h-11 items-center gap-1.5 rounded-full bg-night/80 pr-4 pl-2.5 text-sm font-bold text-paper ring-1 ring-sage/50"
            >
              <ArrowLeft className="size-5" aria-hidden />
              {origin.fromLabel}
            </Link>
          ) : (
            <Link
              to="/"
              className="pointer-events-auto font-display text-2xl leading-none font-black tracking-wide text-paper"
            >
              Path
            </Link>
          )}
          <h1 className="mt-2 truncate font-display text-xl leading-tight font-black text-paper">{mapName}</h1>
        </div>
        <Link
          to="/settings"
          state={{ from: location.pathname, origin }}''')
s=s.replace('import { Settings as SettingsIcon } from "lucide-react";','import { ArrowLeft, Settings as SettingsIcon } from "lucide-react";')
s=s.replace('import { Link, useLocation, useParams } from "react-router";','import { Link, useLocation, useNavigate, useParams } from "react-router";')
s=s.replace('import { useReducedMotion, useTripAvoidStairs } from "../lib/preferences";','import { readMapOrigin } from "../lib/maps";\nimport { useReducedMotion, useTripAvoidStairs } from "../lib/preferences";')
open(g,'w',encoding='utf-8',newline='').write(s)

st='src/routes/Settings.tsx'
edit(st,'import { Link, useLocation } from "react-router";','import { Link, useLocation, useNavigate } from "react-router";')
edit(st,'''  const backTo = (location.state as { from?: string } | null)?.from;''','''  const navigate = useNavigate();
  const { from: backTo, origin } = (location.state as { from?: string; origin?: unknown } | null) ?? {};''')
edit(st,'''          <Link to={backTo} className="text-sm font-bold text-rust underline underline-offset-4">''','''          <Link
            to={backTo}
            state={origin}
            onClick={(event) => {
              // Step back so the map keeps its "← Community" or "← Your maps" button.
              if ((window.history.state as { idx?: number } | null)?.idx) {
                event.preventDefault();
                navigate(-1);
              }
            }}
            className="text-sm font-bold text-rust underline underline-offset-4"
          >''')
